#!/usr/bin/env python3
# SPDX-License-Identifier: Apache-2.0
"""Generate Compose services for 1-10 Slurm compute nodes.

Slurm needs a distinct hostname and SLURM_NODENAME for each node, so Compose's
--scale cannot replace explicit services. The images define slurmnode[1-10].

Run from docker/: python3 generate-compose.py [--nodes N] [--output FILE]
"""

import argparse
from pathlib import Path

HEADER = """# SPDX-License-Identifier: Apache-2.0

# Generated by generate-compose.py --nodes {nodes}. Do not hand-edit;
# re-run the script to change the node count.
x-node-common: &node-common
  image: ghcr.io/noaa-gsl/dockerspackstackslurmcluster/slurm-spack-stack-node:ubuntu-${{UBUNTU_VERSION:-26.04}}-spack-stack-${{SPACK_STACK_VERSION:-2.1.0}}
  shm_size: '4g'
  user: admin
  volumes:
    - home-vol:/home/admin
    - opt-vol:/opt:ro
    - ..:/home/admin/chiltepin
  depends_on:
    slurmmaster:
      condition: service_started
    slurmfrontend:
      condition: service_healthy
  healthcheck:
    test: ["CMD", "ssh", "-o", "StrictHostKeyChecking=no", "admin@localhost", "hostname"]
    interval: 2s
    timeout: 2s
    retries: 10
    start_period: 5s

services:
  slurmfrontend:
    image: ghcr.io/noaa-gsl/dockerspackstackslurmcluster/slurm-spack-stack-frontend:ubuntu-${{UBUNTU_VERSION:-26.04}}-spack-stack-${{SPACK_STACK_VERSION:-2.1.0}}
    container_name: ${{CLUSTER_NAME:-chiltepin}}-frontend
    shm_size: '4g'
    hostname: slurmfrontend
    user: admin
    volumes:
      - home-vol:/home/admin
      - opt-vol:/opt
      - ..:/home/admin/chiltepin
    healthcheck:
      test: ["CMD", "test", "-f", "/tmp/ssh-ready"]
      interval: 5s
      timeout: 2s
      retries: 250
      start_period: 60s

  slurmmaster:
    image: ghcr.io/noaa-gsl/dockerspackstackslurmcluster/slurm-spack-stack-master:ubuntu-${{UBUNTU_VERSION:-26.04}}-spack-stack-${{SPACK_STACK_VERSION:-2.1.0}}
    container_name: ${{CLUSTER_NAME:-chiltepin}}-master
    shm_size: '4g'
    hostname: slurmmaster
    user: admin
    volumes:
      - home-vol:/home/admin
      - opt-vol:/opt:ro
      - ..:/home/admin/chiltepin
    environment:
      - SLURM_CPUS_ON_NODE=8
    depends_on:
      slurmfrontend:
        condition: service_healthy
"""

NODE_TEMPLATE = """
  slurmnode{n}:
    <<: *node-common
    container_name: ${{CLUSTER_NAME:-chiltepin}}-node{n}
    hostname: slurmnode{n}
    environment:
      - SLURM_NODENAME=slurmnode{n}
      - SLURM_CPUS_ON_NODE=8
"""

FOOTER = """
volumes:
  home-vol:
  opt-vol:
"""

MAX_NODES = 10


def build_compose(nodes: int) -> str:
    if not 1 <= nodes <= MAX_NODES:
        raise ValueError(f"--nodes must be between 1 and {MAX_NODES}")
    parts = [HEADER.format(nodes=nodes)]
    parts.extend(NODE_TEMPLATE.format(n=i) for i in range(1, nodes + 1))
    parts.append(FOOTER)
    return "".join(parts)


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--nodes",
        type=int,
        default=5,
        help=f"number of compute nodes (default: 5, max: {MAX_NODES})",
    )
    parser.add_argument(
        "--output",
        type=Path,
        default=Path("docker-compose.yml"),
        help="output file path (default: docker-compose.yml)",
    )
    args = parser.parse_args()
    try:
        compose = build_compose(args.nodes)
    except ValueError as exc:
        parser.error(str(exc))
    args.output.write_text(compose, encoding="utf-8")
    print(f"Wrote {args.output} with {args.nodes} node service(s).")


if __name__ == "__main__":
    main()
